Below are the solution files to create a validation script for the specified pipeline outputs. The script will check for the existence and content of the required output files and generate a summary JSON report.

```plaintext
<solution_file path="src/validate_outputs.py">
import os
import json

def check_file_exists(file_path):
    return os.path.exists(file_path)

def check_file_not_empty(file_path):
    return os.path.getsize(file_path) > 0

def validate():
    checks = [
        {
            "check_name": "Check if outputs/t01_selected_indicators.csv exists and is not empty",
            "file_path": "outputs/t01_selected_indicators.csv",
            "check_function": lambda path: check_file_exists(path) and check_file_not_empty(path)
        },
        {
            "check_name": "Check if outputs/t05_clean_stops.csv exists and is not empty",
            "file_path": "outputs/t05_clean_stops.csv",
            "check_function": lambda path: check_file_exists(path) and check_file_not_empty(path)
        },
        {
            "check_name": "Check if outputs/t08_pois_clean.csv exists and is not empty",
            "file_path": "outputs/t08_pois_clean.csv",
            "check_function": lambda path: check_file_exists(path) and check_file_not_empty(path)
        },
        {
            "check_name": "Check if outputs/t10_accessibility_scores.csv exists and is not empty",
            "file_path": "outputs/t10_accessibility_scores.csv",
            "check_function": lambda path: check_file_exists(path) and check_file_not_empty(path)
        },
        {
            "check_name": "Check if outputs/t13_city_clusters.csv exists and is not empty",
            "file_path": "outputs/t13_city_clusters.csv",
            "check_function": lambda path: check_file_exists(path) and check_file_not_empty(path)
        },
    ]

    results = []
    for check in checks:
        passed = check["check_function"](check["file_path"])
        results.append({
            "check_name": check["check_name"],
            "passed": passed,
            "message": "Passed" if passed else f"Failed: {check['file_path']} does not exist or is empty"
        })

    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(results, f, indent=4)

if __name__ == "__main__":
    validate()
</solution_file>

